const allItems = $input.all();
const existingUrls = new Set();
const existingKeys = new Set();
const newJobs = [];

for (const item of allItems) {
  const j = item.json;
  if (j._isExisting) {
    if (j.job_url) existingUrls.add((j.job_url||'').trim().toLowerCase());
    const k = `${(j.company||'').toLowerCase()}_${(j.job_title||'').toLowerCase()}`;
    if (k.length > 2) existingKeys.add(k);
  } else if (j.source) {
    newJobs.push(item);
  }
}

const seenUrls = new Set();
const seenKeys = new Set();
const unique = [];

for (const item of newJobs) {
  const j = item.json;
  const url = (j.job_url||'').trim().toLowerCase();
  const key = `${(j.company||'').toLowerCase()}_${(j.job_title||'').toLowerCase()}`;
  if (!url) continue;
  if (existingUrls.has(url) || seenUrls.has(url)) continue;
  if (key.length > 2 && (existingKeys.has(key) || seenKeys.has(key))) continue;
  seenUrls.add(url);
  if (key.length > 2) seenKeys.add(key);
  unique.push({ json: j });
}

return unique;

