const result = [];
for (const item of $input.all()) {
  const txt = item.json?.content?.[0]?.text || '{}';
  let ai = {};
  try { const m = txt.match(/\{[\s\S]*\}/); if (m) ai = JSON.parse(m[0]); } catch(e) {}
  result.push({ json: {
    taiwan_eligible: ai.taiwan_eligible || 'unclear',
    taiwan_reason: ai.reason || '',
    location_risk: ai.location_risk || 'medium',
    timezone_risk: ai.timezone_risk || 'medium',
    contractor_possible: ai.contractor_possible || 'unclear',
    decision: ai.decision || 'manual_check'
  }});
}
return result;

const result = [];

for (const item of $input.all()) {
  const j = item.json;
  const allText = [j.job_title,j.description,j.tags,j.location_text].join(' ').toLowerCase();

  // --- ASYNC LEVEL ---
  const asyncReject = ['strict 9','fixed us hours','fixed est','fixed pst','fixed cet','daily live call','must overlap full business day'];
  const asyncHigh = ['async','asynchronous','fully async','no meetings','low meeting culture'];
  const asyncMed = ['flexible hours','flexible schedule','distributed team','work across time zones','time zone agnostic','flexible working'];
  const asyncLow = ['remote first','remote-first','distributed'];
  let async_level = 'unknown';
  if (asyncReject.some(p=>allText.includes(p))) async_level='low';
  else if (asyncHigh.some(p=>allText.includes(p))) async_level='high';
  else if (asyncMed.some(p=>allText.includes(p))) async_level='medium';
  else if (asyncLow.some(p=>allText.includes(p))) async_level='low';

  // --- ROLE CATEGORY ---
  const ROLES = {
    'data analyst': ['data analyst','data analysis'],
    'data scientist': ['data scientist','junior data scientist','machine learning','ml engineer'],
    'bi analyst': ['business intelligence','bi analyst','bi developer','looker','tableau','power bi'],
    'marketing analyst': ['marketing analyst','performance marketing','digital marketing analyst','growth analyst','marketing data','marketing attribution'],
    'ai automation': ['ai automation','ai workflow','automation specialist','n8n','zapier','make.com','workflow automation'],
    'ai marketing': ['ai marketing','martech','marketing ai'],
    'growth': ['growth hacker','growth marketer','growth manager'],
    'creative strategist': ['creative strategist','creative data'],
    'general marketing': ['seo','ppc','paid media','google ads','meta ads','facebook ads','sem']
  };
  let role_category = 'other';
  for (const [cat, pats] of Object.entries(ROLES)) {
    if (pats.some(p=>allText.includes(p))) { role_category=cat; break; }
  }

  // --- SCORE ---
  let score = 0;
  // Taiwan eligibility (0-40)
  const te = j.taiwan_eligible;
  const lr = j.location_risk;
  if (te==='yes' && lr==='low') score+=40;
  else if (te==='yes') score+=35;
  else if (allText.includes('apac')||allText.includes('asia pacific')) score+=30;
  else if (te==='unclear' && lr!=='high') score+=20;

  // Async fit (0-25)
  if (async_level==='high') score+=25;
  else if (async_level==='medium') score+=20;
  else if (async_level==='low') score+=10;
  else score+=10; // default remote gets some points

  // Role fit (0-25)
  const topRoles = ['data analyst','data scientist','bi analyst','marketing analyst','ai automation','ai marketing','growth'];
  if (topRoles.includes(role_category)) score+=25;
  else if (role_category!=='other') score+=15;

  // Salary (0-25)
  const salaryStr = (j.salary||'').replace(/[,$k]/gi,'');
  const salNum = parseInt((salaryStr.match(/(\d+)/)||[])[1]||'0');
  if (salNum > 0) {
    const monthly = salNum > 10000 ? salNum/12 : salNum;
    if (monthly>=5000) score+=25;
    else if (monthly>=3000) score+=15;
    else score+=10;
  }

  // Why good fit
  const why = [];
  if (te==='yes') why.push('Taiwan eligible');
  if (j.contractor_possible==='yes') why.push('contractor friendly');
  if (async_level==='high') why.push('fully async');
  else if (async_level==='medium') why.push('flexible hours');
  if (role_category!=='other') why.push(`role match: ${role_category}`);
  if (j.salary) why.push('salary listed');

  result.push({ json: {
    ...j,
    async_level,
    role_category,
    why_good_fit: why.join('; '),
    score
  }});
}
return result;

const today = new Date().toISOString().split('T')[0];
const allJobs = $input.all().map(i=>i.json).filter(j=>j.date_found===today && j.score);
const topJobs = allJobs.filter(j=>Number(j.score)>=70).sort((a,b)=>Number(b.score)-Number(a.score));
const highPriority = topJobs.filter(j=>Number(j.score)>=85);
const manualCheck = topJobs.filter(j=>j.taiwan_eligible==='unclear');

if (topJobs.length===0) {
  return [{ json: {
    subject: `Daily Taiwan Jobs — No matches today (${today})`,
    html_body: `<p>No new qualifying jobs found today (${today}). The workflow ran successfully but nothing passed all filters. Keep going.</p>`
  }}];
}

let html = `<div style="font-family:Arial,sans-serif;max-width:700px;margin:0 auto">`;
html += `<h2 style="color:#1a1a2e">Daily Taiwan Eligible Async Remote Jobs</h2>`;
html += `<p style="color:#666">Date: ${today} &nbsp;|&nbsp; Total qualifying: <b>${topJobs.length}</b>`;
if (highPriority.length) html += ` &nbsp;|&nbsp; <span style="color:#e63946;font-weight:bold">HIGH PRIORITY: ${highPriority.length}</span>`;
html += `</p><hr>`;

topJobs.slice(0,15).forEach((job,i)=>{
  const score = Number(job.score);
  const border = score>=85 ? '4px solid #e63946' : score>=75 ? '4px solid #f4a261' : '4px solid #457b9d';
  const badge = score>=85 ? '<span style="background:#e63946;color:white;padding:2px 8px;border-radius:12px;font-size:12px;margin-left:8px">APPLY NOW</span>' : '';
  html += `<div style="border-left:${border};padding:12px 16px;margin:16px 0;background:#fafafa;border-radius:0 6px 6px 0">`;
  html += `<h3 style="margin:0 0 6px">${i+1}. ${job.job_title}${badge}</h3>`;
  html += `<p style="margin:4px 0;color:#333"><b>Company:</b> ${job.company}</p>`;
  html += `<p style="margin:4px 0"><b>Score:</b> ${score}/100 &nbsp;|&nbsp; <b>Taiwan eligible:</b> ${job.taiwan_eligible} &nbsp;|&nbsp; <b>Async:</b> ${job.async_level}</p>`;
  html += `<p style="margin:4px 0;color:#555"><b>Reason:</b> ${job.taiwan_reason||'N/A'}</p>`;
  html += `<p style="margin:4px 0"><b>Timezone risk:</b> ${job.timezone_risk} &nbsp;|&nbsp; <b>Salary:</b> ${job.salary||'Not listed'}</p>`;
  html += `<p style="margin:4px 0;color:#444"><b>Why Jerry fits:</b> ${job.why_good_fit||'N/A'}</p>`;
  html += `<p style="margin:8px 0 4px"><a href="${job.job_url}" style="color:#1d70b8;font-weight:bold">Apply here →</a></p>`;
  html += `</div>`;
});

if (manualCheck.length) {
  html += `<h3 style="color:#f4a261">Manual Check Required</h3><ul>`;
  manualCheck.slice(0,5).forEach(j=>{
    html += `<li><a href="${j.job_url}">${j.job_title} at ${j.company}</a> — Score: ${j.score} — ${j.taiwan_reason||'eligibility unclear'}</li>`;
  });
  html += `</ul>`;
}

html += `<hr><p style="color:#aaa;font-size:12px">Powered by Taiwan Job Hunter n8n workflow | One rule: I can do this job while living in Taiwan, without moving, without foreign work auth, without destroying my sleep schedule.</p></div>`;

return [{ json: {
  subject: `${highPriority.length>0?'🔥 ':''}Daily Taiwan Jobs — ${topJobs.length} matches, ${highPriority.length} high priority (${today})`,
  html_body: html
}}];
